func emitPrimitiveToJson(keyLit: string; fieldAccess: NimNode;
    kind: TypeKind): NimNode =
  ## Generate result["key"] = <serialize>(x.field) for primitive types.
  let kl = newStrLitNode(keyLit)
  case kind
  of tkString:
    quote do: result[`kl`] = newJString(`fieldAccess`)
  of tkInt:
    quote do: result[`kl`] = newJInt(`fieldAccess`)
  of tkFloat:
    quote do: result[`kl`] = newJFloat(`fieldAccess`)
  of tkBool:
    quote do: result[`kl`] = newJBool(`fieldAccess`)
  of tkEnum:
    quote do: result[`kl`] = newJString($`fieldAccess`)
  of tkJsonNode:
    quote do: result[`kl`] = `fieldAccess`
  else:
    newEmptyNode()

func emitDistinctToJson(keyLit: string; fieldAccess: NimNode;
    baseKind: TypeKind; baseNode: NimNode): NimNode =
  ## Generate toJson for distinct types by casting to base type.
  let kl = newStrLitNode(keyLit)
  let castExpr = nnkCall.newTree(baseNode, fieldAccess)
  case baseKind
  of tkString:
    quote do: result[`kl`] = newJString(`castExpr`)
  of tkInt:
    quote do: result[`kl`] = newJInt(`castExpr`)
  of tkFloat:
    quote do: result[`kl`] = newJFloat(`castExpr`)
  of tkBool:
    quote do: result[`kl`] = newJBool(`castExpr`)
  of tkEnum:
    quote do: result[`kl`] = newJString($`castExpr`)
  else:
    error("deriveJsonCodec: unsupported distinct base kind for field '" &
        keyLit & "'", baseNode)

func emitSeqFieldToJson(keyLit: string; fieldAccess: NimNode;
    typeNode: NimNode): NimNode =
  ## Generate result["key"] = arr for seq[T] fields.
  let kl = newStrLitNode(keyLit)
  let elemTypeNode = typeNode[1]
  let elemKind = classifyType(elemTypeNode)
  let arrIdent = genSym(nskVar, "arr")
  let elemIdent = genSym(nskForVar, "elem")
  let addCall = case elemKind
  of tkString:
    nnkCall.newTree(ident("newJString"), elemIdent)
  of tkInt:
    nnkCall.newTree(ident("newJInt"), elemIdent)
  of tkFloat:
    nnkCall.newTree(ident("newJFloat"), elemIdent)
  of tkBool:
    nnkCall.newTree(ident("newJBool"), elemIdent)
  else:
    nnkCall.newTree(ident("toJson"), elemIdent)
  let addStmt = nnkCall.newTree(ident("add"), arrIdent, addCall)
  let forLoop = nnkForStmt.newTree(elemIdent, fieldAccess, addStmt)
  let initCall = nnkCall.newTree(ident("newJArray"))
  result = nnkStmtList.newTree(
    nnkBlockStmt.newTree(newEmptyNode(),
      nnkStmtList.newTree(
        nnkVarSection.newTree(nnkIdentDefs.newTree(arrIdent, newEmptyNode(), initCall)),
        forLoop,
        nnkAsgn.newTree(nnkBracketExpr.newTree(ident("result"), kl), arrIdent)
      )
    )
  )

func emitFieldToJson(field: FieldInfo; objRef: NimNode): NimNode =
  ## Generate the toJson statement for a single field.
  let fieldAccess = newDotExpr(objRef, field.nameNode)
  let keyLit = field.name
  case field.typeKind
  of tkString, tkInt, tkFloat, tkBool, tkEnum, tkJsonNode:
    emitPrimitiveToJson(keyLit, fieldAccess, field.typeKind)
  of tkDistinct:
    emitDistinctToJson(keyLit, fieldAccess, field.baseTypeKind,
        field.baseTypeNode)
  of tkSeq:
    emitSeqFieldToJson(keyLit, fieldAccess, field.typeNode)
  of tkOption:
    let kl = newStrLitNode(keyLit)
    quote do:
      if `fieldAccess`.isSome:
        result[`kl`] = toJson(`fieldAccess`.get())
      else:
        result[`kl`] = newJNull()
  of tkTable:
    let kl = newStrLitNode(keyLit)
    quote do:
      block:
        var tbl = newJObject()
        for k, v in `fieldAccess`:
          tbl[k] = toJson(v)
        result[`kl`] = tbl
  of tkObject, tkRefObject:
    let kl = newStrLitNode(keyLit)
    quote do: result[`kl`] = toJson(`fieldAccess`)
  else:
    error("deriveJsonCodec: unsupported field type for '" & keyLit & "'",
        field.typeNode)

func emitObjectToJson*(typeName: NimNode; info: TypeInfo): NimNode =
  ## Generate toJson proc for an object type.
  let procName = ident("toJson")
  let paramX = ident("x")
  let bodyStmts = newStmtList()

  for field in info.memberFields:
    if info.hasDiscriminator and field.name == info.discFieldName:
      continue  # discriminator handled separately in case branch
    bodyStmts.add(emitFieldToJson(field, paramX))

  if info.hasDiscriminator:
    let discAccess = newDotExpr(paramX, info.discNameNode)
    let discKey = newStrLitNode(info.discFieldName)
    bodyStmts.add(quote do:
      result[`discKey`] = newJString($`discAccess`)
    )
    let caseStmt = nnkCaseStmt.newTree(discAccess)
    for branch in info.branches:
      let ofBranch = nnkOfBranch.newTree()
      for dv in branch.discValues:
        ofBranch.add(dv)
      let branchStmts = newStmtList()
      for bf in branch.branchFields:
        branchStmts.add(emitFieldToJson(bf, paramX))
      ofBranch.add(branchStmts)
      caseStmt.add(ofBranch)
    if info.elseFields.len > 0:
      let elseBranch = nnkElse.newTree(newStmtList())
      for ef in info.elseFields:
        elseBranch[0].add(emitFieldToJson(ef, paramX))
      caseStmt.add(elseBranch)
    bodyStmts.add(caseStmt)

  quote do:
    func `procName`*(`paramX`: `typeName`): JsonNode
        {.noSideEffect, raises: [].} =
      ## [SEE: nim_effect_system_quirks.md]
      {.cast(noSideEffect).}:
        result = newJObject()
        `bodyStmts`

func emitEnumToJson*(typeName: NimNode; enumValues: seq[string]): NimNode =
  ## Generate toJson proc for an enum type.
  let procName = ident("toJson")
  let paramX = ident("x")
  quote do:
    func `procName`*(`paramX`: `typeName`): JsonNode
        {.noSideEffect, raises: [].} =
      newJString($`paramX`)

