func emitEnumFromJson*(typeName: NimNode;
    enumValues: seq[string]): NimNode =
  ## Generate fromJson proc for an enum type.
  let procName = ident("fromJson")
  let paramNode = ident("node")
  let paramDisc = ident("_")
  let typeNameStr = newStrLitNode($typeName)

  let caseStmt = nnkCaseStmt.newTree(
    nnkCall.newTree(ident("getStr"), paramNode))
  for val in enumValues:
    let valIdent = ident(val)
    let valStr = newStrLitNode(val)
    caseStmt.add(nnkOfBranch.newTree(valStr,
        quote do: return ok(`valIdent`)))
  let errStr = newStrLitNode("Unknown " & $typeName & " value: ")
  caseStmt.add(nnkElse.newTree(quote do:
    return err(`errStr` & `paramNode`.getStr())
  ))

  quote do:
    func `procName`*(`paramNode`: JsonNode; `paramDisc`: typedesc[`typeName`]):
        Result[`typeName`, string] {.noSideEffect, raises: [].} =
      if `paramNode`.kind != JString:
        return err("Expected JSON string for " & `typeNameStr`)
      `caseStmt`

