func emitPrimitiveFieldFromJson(fieldName: string; fieldIdent: NimNode;
    keyLit: NimNode; resRef: NimNode; nodeRef: NimNode;
    typeKind: TypeKind): NimNode =
  ## Generate fromJson for tkString/tkInt/tkFloat/tkBool fields.
  let errMissing = newStrLitNode("Missing required field '" & fieldName & "'")
  let kindNode = case typeKind
    of tkString: ident("JString")
    of tkInt: ident("JInt")
    of tkFloat: ident("JFloat")
    of tkBool: ident("JBool")
    else: ident("JString")
  let errType = newStrLitNode("Wrong type for field '" & fieldName & "'")
  let getter = case typeKind
    of tkString: nnkCall.newTree(ident("getStr"),
        nnkBracketExpr.newTree(nodeRef, keyLit))
    of tkInt: nnkCall.newTree(ident("getInt"),
        nnkBracketExpr.newTree(nodeRef, keyLit))
    of tkFloat: nnkCall.newTree(ident("getFloat"),
        nnkBracketExpr.newTree(nodeRef, keyLit))
    of tkBool: nnkCall.newTree(ident("getBool"),
        nnkBracketExpr.newTree(nodeRef, keyLit))
    else: nnkCall.newTree(ident("getStr"),
        nnkBracketExpr.newTree(nodeRef, keyLit))
  quote do:
    if not `nodeRef`.hasKey(`keyLit`):
      return err(`errMissing`)
    if `nodeRef`[`keyLit`].kind != `kindNode`:
      return err(`errType`)
    `resRef`.`fieldIdent` = `getter`

func emitEnumFieldFromJson(fieldTypeNode: NimNode; fieldName: string;
    fieldIdent: NimNode; keyLit: NimNode; resRef: NimNode;
    nodeRef: NimNode): NimNode =
  ## Generate fromJson for tkEnum fields.
  let errMissing = newStrLitNode("Missing required field '" & fieldName & "'")
  let errType = newStrLitNode("Wrong type for field '" & fieldName & "'")
  let convCall = nnkCall.newTree(ident("fromJson"),
    nnkBracketExpr.newTree(nodeRef, keyLit),
    nnkBracketExpr.newTree(ident("typedesc"), fieldTypeNode))
  quote do:
    if not `nodeRef`.hasKey(`keyLit`):
      return err(`errMissing`)
    if `nodeRef`[`keyLit`].kind != JString:
      return err(`errType`)
    block:
      let convResult = `convCall`
      if not convResult.ok:
        return err(convResult.err)
      `resRef`.`fieldIdent` = convResult.value

func emitDistinctFieldFromJson(fieldTypeNode: NimNode; fieldName: string;
    fieldIdent: NimNode; keyLit: NimNode; resRef: NimNode;
    nodeRef: NimNode; baseTypeKind: TypeKind): NimNode =
  ## Generate fromJson for tkDistinct fields.
  let errMissing = newStrLitNode("Missing required field '" & fieldName & "'")
  let errType = newStrLitNode("Wrong type for field '" & fieldName & "'")
  let kindNode = case baseTypeKind
    of tkString: ident("JString")
    of tkInt: ident("JInt")
    of tkFloat: ident("JFloat")
    of tkBool: ident("JBool")
    else: ident("JString")
  let getter = case baseTypeKind
    of tkString: nnkCall.newTree(ident("getStr"),
        nnkBracketExpr.newTree(nodeRef, keyLit))
    of tkInt: nnkCall.newTree(ident("getInt"),
        nnkBracketExpr.newTree(nodeRef, keyLit))
    of tkFloat: nnkCall.newTree(ident("getFloat"),
        nnkBracketExpr.newTree(nodeRef, keyLit))
    of tkBool: nnkCall.newTree(ident("getBool"),
        nnkBracketExpr.newTree(nodeRef, keyLit))
    else: nnkCall.newTree(ident("getStr"),
        nnkBracketExpr.newTree(nodeRef, keyLit))
  let wrapCall = nnkCall.newTree(fieldTypeNode, getter)
  quote do:
    if not `nodeRef`.hasKey(`keyLit`):
      return err(`errMissing`)
    if `nodeRef`[`keyLit`].kind != `kindNode`:
      return err(`errType`)
    `resRef`.`fieldIdent` = `wrapCall`

func emitSeqFieldFromJson(fieldTypeNode: NimNode; fieldName: string;
    fieldIdent: NimNode; keyLit: NimNode; resRef: NimNode;
    nodeRef: NimNode): NimNode =
  ## Generate fromJson for tkSeq fields.
  let errMissing = newStrLitNode("Missing required field '" & fieldName & "'")
  let errArr = newStrLitNode("Expected JSON array for field '" & fieldName & "'")
  let elemType = fieldTypeNode[1]  # seq[T] → T is child[1]
  let elemKind = classifyType(elemType)
  let arrNodeIdent = genSym(nskLet, "arrNode")
  let arrIdent = genSym(nskVar, "arr")
  let elemIdent = genSym(nskForVar, "elem")
  # Build the loop body based on element type
  let loopBody = case elemKind
  of tkString:
    quote do:
      `arrIdent`.add(`elemIdent`.getStr())
  of tkInt:
    quote do:
      `arrIdent`.add(`elemIdent`.getInt())
  of tkFloat:
    quote do:
      `arrIdent`.add(`elemIdent`.getFloat())
  of tkBool:
    quote do:
      `arrIdent`.add(`elemIdent`.getBool())
  else:
    let convCall = nnkCall.newTree(ident("fromJson"), elemIdent,
      nnkBracketExpr.newTree(ident("typedesc"), elemType))
    quote do:
      let r = `convCall`
      if not r.ok: return err(r.err)
      `arrIdent`.add(r.value)
  let forLoop = nnkForStmt.newTree(elemIdent,
    nnkDotExpr.newTree(arrNodeIdent, ident("elems")),
    loopBody)
  quote do:
    if not `nodeRef`.hasKey(`keyLit`):
      return err(`errMissing`)
    let `arrNodeIdent` = `nodeRef`[`keyLit`]
    if `arrNodeIdent`.kind != JArray:
      return err(`errArr`)
    var `arrIdent`: `fieldTypeNode`
    `forLoop`
    `resRef`.`fieldIdent` = `arrIdent`

func emitOptionFieldFromJson(fieldTypeNode: NimNode; fieldIdent: NimNode;
    keyLit: NimNode; resRef: NimNode; nodeRef: NimNode): NimNode =
  ## Generate fromJson for tkOption fields.
  let convCall = nnkCall.newTree(ident("fromJson"),
    nnkBracketExpr.newTree(nodeRef, keyLit),
    nnkBracketExpr.newTree(ident("typedesc"), fieldTypeNode))
  quote do:
    if `nodeRef`.hasKey(`keyLit`) and `nodeRef`[`keyLit`].kind != JNull:
      let r = `convCall`
      if not r.ok: return err(r.err)
      `resRef`.`fieldIdent` = some(r.value)

func emitTableFieldFromJson(fieldTypeNode: NimNode; fieldName: string;
    fieldIdent: NimNode; keyLit: NimNode; resRef: NimNode;
    nodeRef: NimNode): NimNode =
  ## Generate fromJson for tkTable fields.
  let errMissing = newStrLitNode("Missing required field '" & fieldName & "'")
  let errObj = newStrLitNode("Expected JSON object for field '" & fieldName & "'")
  let valType = fieldTypeNode[2]  # Table[K, V] → V is child[2]
  let convCall = nnkCall.newTree(ident("fromJson"), ident("v"),
    nnkBracketExpr.newTree(ident("typedesc"), valType))
  quote do:
    if not `nodeRef`.hasKey(`keyLit`):
      return err(`errMissing`)
    let tblNode = `nodeRef`[`keyLit`]
    if tblNode.kind != JObject:
      return err(`errObj`)
    for k, v in tblNode.fields:
      let r = `convCall`
      if not r.ok: return err(r.err)
      `resRef`.`fieldIdent`[k] = r.value

func emitObjectFieldFromJson(fieldTypeNode: NimNode; fieldName: string;
    fieldIdent: NimNode; keyLit: NimNode; resRef: NimNode;
    nodeRef: NimNode): NimNode =
  ## Generate fromJson for tkObject/tkRefObject fields.
  let errMissing = newStrLitNode("Missing required field '" & fieldName & "'")
  let convCall = nnkCall.newTree(ident("fromJson"),
    nnkBracketExpr.newTree(nodeRef, keyLit),
    nnkBracketExpr.newTree(ident("typedesc"), fieldTypeNode))
  quote do:
    if not `nodeRef`.hasKey(`keyLit`):
      return err(`errMissing`)
    block:
      let r = `convCall`
      if not r.ok: return err(r.err)
      `resRef`.`fieldIdent` = r.value

func emitFieldFromJson(field: FieldInfo; resRef: NimNode;
    nodeRef: NimNode): NimNode =
  ## Generate the fromJson statement for a single field.
  let fieldName = field.name
  let fieldIdent = field.nameNode
  let keyLit = newStrLitNode(fieldName)
  let fieldTypeNode = field.typeNode
  case field.typeKind
  of tkString, tkInt, tkFloat, tkBool:
    emitPrimitiveFieldFromJson(fieldName, fieldIdent, keyLit, resRef,
        nodeRef, field.typeKind)
  of tkEnum:
    emitEnumFieldFromJson(fieldTypeNode, fieldName, fieldIdent, keyLit,
        resRef, nodeRef)
  of tkDistinct:
    emitDistinctFieldFromJson(fieldTypeNode, fieldName, fieldIdent, keyLit,
        resRef, nodeRef, field.baseTypeKind)
  of tkSeq:
    emitSeqFieldFromJson(fieldTypeNode, fieldName, fieldIdent, keyLit,
        resRef, nodeRef)
  of tkOption:
    emitOptionFieldFromJson(fieldTypeNode, fieldIdent, keyLit, resRef,
        nodeRef)
  of tkTable:
    emitTableFieldFromJson(fieldTypeNode, fieldName, fieldIdent, keyLit,
        resRef, nodeRef)
  of tkObject, tkRefObject:
    emitObjectFieldFromJson(fieldTypeNode, fieldName, fieldIdent, keyLit,
        resRef, nodeRef)
  else:
    error("deriveJsonCodec: unsupported field type for fromJson '" &
        fieldName & "'", field.typeNode)

func isFieldInBranch(info: TypeInfo; fieldName: string): bool =
  ## Check if a field belongs to any variant branch or else fields.
  for branch in info.branches:
    for bf in branch.branchFields:
      if bf.name == fieldName: return true
  for ef in info.elseFields:
    if ef.name == fieldName: return true

func emitFieldToLet(field: FieldInfo; paramNode: NimNode):
    (NimNode, NimNode) =
  ## Parse a JSON field into a let variable for constructor-style fromJson.
  ## Returns (letStatement, letVarIdent).
  let letVar = genSym(nskLet, field.name & "_val")
  let keyLit = newStrLitNode(field.name)
  result = (newStmtList(), letVar)
  case field.typeKind
  of tkString, tkInt, tkFloat, tkBool:
    let errMissing = newStrLitNode("Missing required field '" & field.name & "'")
    let kindNode = case field.typeKind
      of tkString: ident("JString")
      of tkInt: ident("JInt")
      of tkFloat: ident("JFloat")
      of tkBool: ident("JBool")
      else: ident("JString")
    let errType = newStrLitNode("Wrong type for field '" & field.name & "'")
    let getter = case field.typeKind
      of tkString: nnkCall.newTree(ident("getStr"),
          nnkBracketExpr.newTree(paramNode, keyLit))
      of tkInt: nnkCall.newTree(ident("getInt"),
          nnkBracketExpr.newTree(paramNode, keyLit))
      of tkFloat: nnkCall.newTree(ident("getFloat"),
          nnkBracketExpr.newTree(paramNode, keyLit))
      of tkBool: nnkCall.newTree(ident("getBool"),
          nnkBracketExpr.newTree(paramNode, keyLit))
      else: nnkCall.newTree(ident("getStr"),
          nnkBracketExpr.newTree(paramNode, keyLit))
    result[0].add(quote do:
      if not `paramNode`.hasKey(`keyLit`):
        return err(`errMissing`)
      if `paramNode`[`keyLit`].kind != `kindNode`:
        return err(`errType`)
    )
    result[0].add(nnkLetSection.newTree(
      nnkIdentDefs.newTree(letVar, newEmptyNode(), getter)))
  of tkEnum:
    let errMissing = newStrLitNode("Missing required field '" & field.name & "'")
    let convCall = nnkCall.newTree(ident("fromJson"),
      nnkBracketExpr.newTree(paramNode, keyLit),
      nnkBracketExpr.newTree(ident("typedesc"), field.typeNode))
    result[0].add(quote do:
      if not `paramNode`.hasKey(`keyLit`):
        return err(`errMissing`)
      if `paramNode`[`keyLit`].kind != JString:
        return err("Wrong type for field '" & `keyLit` & "'")
    )
    let convResult = genSym(nskLet, "conv")
    result[0].add(nnkLetSection.newTree(
      nnkIdentDefs.newTree(convResult, newEmptyNode(), convCall)))
    result[0].add(quote do:
      if not `convResult`.ok:
        return err(`convResult`.err)
    )
    result[0].add(nnkLetSection.newTree(
      nnkIdentDefs.newTree(letVar, newEmptyNode(),
        nnkDotExpr.newTree(convResult, ident("value")))))
  of tkSeq:
    let errMissing = newStrLitNode("Missing required field '" & field.name & "'")
    let convCall = nnkCall.newTree(ident("fromJson"),
      nnkBracketExpr.newTree(paramNode, keyLit),
      nnkBracketExpr.newTree(ident("typedesc"), field.typeNode))
    result[0].add(quote do:
      if not `paramNode`.hasKey(`keyLit`):
        return err(`errMissing`)
      if `paramNode`[`keyLit`].kind != JArray:
        return err("Expected JArray for field '" & `keyLit` & "'")
    )
    let convResult = genSym(nskLet, "conv")
    result[0].add(nnkLetSection.newTree(
      nnkIdentDefs.newTree(convResult, newEmptyNode(), convCall)))
    result[0].add(quote do:
      if not `convResult`.ok:
        return err(`convResult`.err)
    )
    result[0].add(nnkLetSection.newTree(
      nnkIdentDefs.newTree(letVar, newEmptyNode(),
        nnkDotExpr.newTree(convResult, ident("value")))))
  else:
    error("deriveJsonCodec: unsupported field type for variant fromJson '" &
        field.name & "'", field.typeNode)

func buildVariantConstructor(info: TypeInfo; paramNode: NimNode): NimNode =
  ## Generate fromJson body for variant objects using constructor syntax.
  ## Avoids CaseTransition by constructing the object in one shot per branch.
  result = newStmtList()
  let discKey = newStrLitNode(info.discFieldName)
  let errDisc = newStrLitNode("Missing discriminator '" &
      info.discFieldName & "'")
  result.add(quote do:
    if not `paramNode`.hasKey(`discKey`):
      return err(`errDisc`)
    if `paramNode`[`discKey`].kind != JString:
      return err("Discriminator must be a string")
  )
  # Parse common fields into let variables
  var fieldPairs: seq[(NimNode, string)]
  for field in info.memberFields:
    if field.name != info.discFieldName and
        not isFieldInBranch(info, field.name):
      let (stmts, letVar) = emitFieldToLet(field, paramNode)
      result.add(stmts)
      fieldPairs.add((letVar, field.name))
  # Case statement on discriminator
  let discAccess = nnkBracketExpr.newTree(paramNode, discKey)
  let getDiscStr = nnkCall.newTree(ident("getStr"), discAccess)
  let caseStmt = nnkCaseStmt.newTree(getDiscStr)
  for branch in info.branches:
    let ofBranch = nnkOfBranch.newTree()
    for dvIdx, dv in branch.discValues:
      let discName = if dvIdx < branch.discValueNames.len:
        branch.discValueNames[dvIdx]
      elif dv.kind == nnkIntLit: $dv.intVal
      else: $dv
      ofBranch.add(newStrLitNode(discName))
    let branchStmts = newStmtList()
    # Parse branch fields into let variables
    var branchPairs: seq[(NimNode, string)]
    for bf in branch.branchFields:
      let (stmts, letVar) = emitFieldToLet(bf, paramNode)
      branchStmts.add(stmts)
      branchPairs.add((letVar, bf.name))
    # Build constructor call
    let typeNameIdent = ident(info.typeName)
    let discNameNode = info.discNameNode
    let firstDiscVal = branch.discValues[0]
    var constructor = nnkObjConstr.newTree(typeNameIdent)
    for (fv, fn) in fieldPairs:
      constructor.add(nnkExprColonExpr.newTree(ident(fn), fv))
    constructor.add(nnkExprColonExpr.newTree(discNameNode, firstDiscVal))
    for (bv, bn) in branchPairs:
      constructor.add(nnkExprColonExpr.newTree(ident(bn), bv))
    let okCall = quote do: ok(`constructor`)
    branchStmts.add(nnkReturnStmt.newTree(okCall))
    ofBranch.add(branchStmts)
    caseStmt.add(ofBranch)
  if info.elseFields.len > 0:
    let elseBranch = nnkElse.newTree(newStmtList())
    let errUnknown2 = newStrLitNode("Unknown discriminator value")
    elseBranch[0].add(nnkReturnStmt.newTree(
      quote do: err(`errUnknown2`)))
    caseStmt.add(elseBranch)
  else:
    let errUnknown = newStrLitNode("Unknown discriminator value")
    caseStmt.add(nnkElse.newTree(quote do:
      return err(`errUnknown`)
    ))
  result.add(caseStmt)

func emitObjectFromJson*(typeName: NimNode; info: TypeInfo): NimNode =
  ## Generate fromJson proc for an object type.
  let procName = ident("fromJson")
  let paramNode = ident("node")
  let paramDisc = ident("_")
  let resRef = ident("res")
  let typeNameStr = newStrLitNode(info.typeName)
  let bodyStmts = newStmtList()
  bodyStmts.add(quote do:
    if `paramNode`.kind != JObject:
      return err("Expected JSON object for " & `typeNameStr`)
  )
  if info.hasDiscriminator:
    # Variant objects use constructor syntax to avoid CaseTransition
    bodyStmts.add(buildVariantConstructor(info, paramNode))
    bodyStmts.add(quote do:
      return err("Unhandled discriminator branch")
    )
  else:
    bodyStmts.add(quote do:
      var `resRef`: `typeName`
    )
    for field in info.memberFields:
      bodyStmts.add(emitFieldFromJson(field, resRef, paramNode))
    bodyStmts.add(quote do:
